/**
 * Who eats whom, as the scene needs it (visual only): the catalogue's food links
 * (`voyage_food_links`), cut to vertebrate predators and prey of a size a viewer
 * would read as hunter and quarry (`food-links.json`, generated by
 * `scripts/ark-behaviour-profiles.mts`). The behaviour schedule keeps a
 * predator's home range a safe distance from its prey's (`spaceHomes`). The
 * server alone decides every meal.
 */

import table from "@/ark-scene/food-links.json";

const data = table as {slugs: string[]; links: Record<string, string>};
const cache = new Map<string, Set<string>>();

/** The species this predator eats (slugs). */
export function preyOf(predator: string): Set<string> {
    let prey = cache.get(predator);
    if (!prey) {
        const row = data.links[predator];
        prey = new Set(row ? row.split(",").map((i) => data.slugs[parseInt(i, 36)]) : []);
        cache.set(predator, prey);
    }
    return prey;
}

export function eats(predator: string, prey: string): boolean {
    return preyOf(predator).has(prey);
}
